tools.cdt.evaluate_script({
  pageId: 2,
  function: () => {
    const result = [];
    // BBC news story headings are typically H2 with data-testid="card-heading" or in <h2>
    const headings = document.querySelectorAll('h2');
    let count = 0;
    for (const h of headings) {
      if (count >= 6) break;
      const text = h.innerText.trim();
      // only consider those that look like headline cards (have a link child)
      if (text && text.length > 15) {
        result.push(text);
        count++;
      }
    }
    return result;
  }
})

